CREATE TABLE "products" (
  "id" VARCHAR(255) PRIMARY KEY,             
  "ean_code" CHAR(13),                       -- EANコード → ean_code
  "product_title" VARCHAR(255),              -- 商品-タイトル → product_title
  "category" VARCHAR(255),                   -- カテゴリ／種別 → category
  "vendor_name" VARCHAR(255),                -- ベンダー・名称 → vendor_name
  "price_usd" NUMERIC,                       -- 価格_数値 → price_usd
  "rating" NUMERIC,                          -- 評価__（RATING） → rating
  "created_at" TIMESTAMP,                    -- 作成日時 → created_at
  "updated_at" TIMESTAMP,                    -- 更新日時 → updated_at
  "is_deleted" BOOLEAN,                      -- 論理削除フラグ → is_deleted
  "deleted_at" TIMESTAMP                     -- 論理削除日時 → deleted_at
);


